const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const utah = ee.FeatureCollection('USGS/FED/US_STATES')
    .filter(ee.Filter.eq('STATE_NAME', 'Utah'))
    .first()
    .geometry();

  const august2020_start = '2020-08-01';
  const august2020_end = '2020-08-31';

  const long_term_start_year = 2015; // SMAP started in 2015
  const long_term_end_year = 2019; // Exclude 2020 for long-term average

  // Define the SMAP collection and band
  const collection = ee.ImageCollection('NASA/SMAP/SPL3SM_P_E')
    .select(['sm_surface', 'sm_surface_quality_flag']);

  // Function to mask out bad quality pixels
  const applyQualityMask = (image) => {
    const qualityFlag = image.select('sm_surface_quality_flag');
    // Mask out pixels where quality flag is not 0 (0 means good quality)
    // Also mask out values outside typical soil moisture range [0, 0.6]
    return image.updateMask(qualityFlag.eq(0))
      .updateMask(image.select('sm_surface').gte(0).and(image.select('sm_surface').lte(0.6)))
      .copyProperties(image, ['system:time_start']);
  };

  // --- Process August 2020 Data ---
  let col2020 = collection.filterDate(august2020_start, august2020_end)
    .filterBounds(utah)
    .map(applyQualityMask);

  const size2020 = await col2020.size().getInfo();
  if (size2020 === 0) {
    console.log("No images found for Utah in August 2020.");
    console.log("C1");
    return;
  }
  console.log(`2020 Images: ${size2020}`);

  const mean2020 = col2020.mean();
  const count2020 = await mean2020.select('sm_surface').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9,
  }).get('sm_surface').getInfo();

  if (count2020 === 0) {
    console.log("No valid pixels for 2020 after masking.");
    console.log("C2");
    return;
  }

  const sm2020 = await mean2020.select('sm_surface').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9,
  }).get('sm_surface').getInfo();

  if (sm2020 === null || isNaN(sm2020)) {
    console.log("2020 soil moisture calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`2020 SM (m^3/m^3): ${sm2020.toFixed(4)} (Pixels: ${count2020})`);

  // --- Process Long-Term Data ---
  let longTermCollections = [];
  for (let year = long_term_start_year; year <= long_term_end_year; year++) {
    const year_start = `${year}-08-01`;
    const year_end = `${year}-08-31`;
    const col_year = collection.filterDate(year_start, year_end)
      .filterBounds(utah)
      .map(applyQualityMask);
    if (await col_year.size().getInfo() > 0) {
      longTermCollections.push(col_year.mean());
    }
  }

  if (longTermCollections.length === 0) {
    console.log(`No images found for Utah for long-term August (${long_term_start_year}-${long_term_end_year}).`);
    console.log("C1");
    return;
  }
  console.log(`Long-term years with data: ${longTermCollections.length}`);

  const longTermMeanImage = ee.ImageCollection(longTermCollections).mean();

  const countLongTerm = await longTermMeanImage.select('sm_surface').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9,
  }).get('sm_surface').getInfo();

  if (countLongTerm === 0) {
    console.log("No valid pixels for long-term average after masking.");
    console.log("C2");
    return;
  }

  const smLongTerm = await longTermMeanImage.select('sm_surface').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9,
  }).get('sm_surface').getInfo();

  if (smLongTerm === null || isNaN(smLongTerm)) {
    console.log("Long-term soil moisture calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`Long-term Avg SM (m^3/m^3): ${smLongTerm.toFixed(4)} (Pixels: ${countLongTerm})`);

  // 5. Validation & Final Answer
  if (sm2020 < smLongTerm) {
    console.log("A"); // Yes, surface soil moisture decreased
  } else {
    console.log("B"); // No, surface soil moisture did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
